package dev.example.orders;

import org.apache.kafka.common.TopicPartition;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaOperations;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.kafka.support.converter.ConversionException;
import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;

// Spring Boot sets this error handler on the listener container factory.
// A failing record is tried up to 4 times, 200, 400 and 800 ms apart, then
// published unchanged to <topic>.DLT and the consumer moves on. Records that
// can never succeed go to the DLT straight away. If the DLT publish itself
// fails, the record is not committed and is processed again.
@Configuration
public class KafkaErrorHandling {

    static final int MAX_RETRIES = 3;

    @Bean
    public DefaultErrorHandler kafkaErrorHandler(KafkaOperations<?, ?> kafka) {
        // Partition -1 lets the producer choose, so the DLT needs no particular
        // partition count.
        DeadLetterPublishingRecoverer deadLetters = new DeadLetterPublishingRecoverer(
                kafka, (record, ex) -> new TopicPartition(record.topic() + ".DLT", -1));

        ExponentialBackOffWithMaxRetries backOff =
                new ExponentialBackOffWithMaxRetries(MAX_RETRIES);
        backOff.setInitialInterval(200);
        backOff.setMultiplier(2);
        backOff.setMaxInterval(800);

        DefaultErrorHandler handler = new DefaultErrorHandler(deadLetters, backOff);
        handler.addNotRetryableExceptions(
                ConversionException.class, OrderNotFoundException.class);
        return handler;
    }
}
