import static org.assertj.core.api.Assertions.assertThat;
import static org.awaitility.Awaitility.await;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Function;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.ImportAutoConfiguration;
import org.springframework.boot.jackson.autoconfigure.JacksonAutoConfiguration;
import org.springframework.boot.kafka.autoconfigure.KafkaAutoConfiguration;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.QueryTimeoutException;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.test.EmbeddedKafkaBroker;
import org.springframework.kafka.test.context.EmbeddedKafka;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

// Only the listener, its error handling and Kafka: no database needed.
@SpringBootTest(classes = {PaymentSettledListener.class, KafkaErrorHandling.class},
        properties = "spring.kafka.bootstrap-servers=${spring.embedded.kafka.brokers}")
@ImportAutoConfiguration({KafkaAutoConfiguration.class, JacksonAutoConfiguration.class})
@EmbeddedKafka(topics = {"payment-settled", "payment-settled.DLT"})
class PaymentSettledListenerTest {

    private static final String TOPIC = "payment-settled";
    private static final String DLT = "payment-settled.DLT";

    @MockitoBean
    OrderService orders;

    @Autowired
    KafkaTemplate<String, String> kafka;

    @Autowired
    EmbeddedKafkaBroker broker;

    // markPaid attempts per order id, as System.nanoTime() values.
    private final Map<String, List<Long>> attempts = new ConcurrentHashMap<>();
    // What markPaid does for an order id; absent means it succeeds.
    private final Map<String, Function<Integer, RuntimeException>> failures =
            new ConcurrentHashMap<>();

    private KafkaConsumer<String, String> dlt;

    @BeforeEach
    void setUp() {
        doAnswer(invocation -> {
            PaymentSettled event = invocation.getArgument(0);
            List<Long> times = attempts.computeIfAbsent(event.orderId(),
                    id -> new CopyOnWriteArrayList<>());
            times.add(System.nanoTime());
            Function<Integer, RuntimeException> failure = failures.get(event.orderId());
            RuntimeException ex = failure == null ? null : failure.apply(times.size());
            if (ex != null) {
                throw ex;
            }
            return null;
        }).when(orders).markPaid(any());

        dlt = new KafkaConsumer<>(Map.of(
                ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, broker.getBrokersAsString(),
                ConsumerConfig.GROUP_ID_CONFIG, "dlt-" + UUID.randomUUID(),
                ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest"),
                new StringDeserializer(), new StringDeserializer());
        dlt.subscribe(List.of(DLT));
    }

    @AfterEach
    void tearDown() {
        dlt.close();
    }

    @Test
    void transientFailureIsRetriedWithBackoffThenDeadLettered() {
        String orderId = newOrderId();
        failures.put(orderId, attempt -> new QueryTimeoutException("db slow"));
        String message = payment(orderId);

        kafka.send(TOPIC, orderId, message);

        ConsumerRecord<String, String> dead = awaitDeadLetter(message);
        assertThat(dead.key()).isEqualTo(orderId);

        List<Long> times = attempts.get(orderId);
        assertThat(times).hasSize(4);
        for (int i = 1; i < times.size(); i++) {
            assertThat(Duration.ofNanos(times.get(i) - times.get(i - 1)))
                    .isGreaterThanOrEqualTo(Duration.ofMillis(100));
        }
        assertThat(Duration.ofNanos(times.getLast() - times.getFirst()))
                .isLessThan(Duration.ofSeconds(5));
    }

    @Test
    void transientFailureThatRecoversIsNotDeadLettered() {
        String orderId = newOrderId();
        failures.put(orderId, attempt ->
                attempt < 3 ? new QueryTimeoutException("db slow") : null);
        String message = payment(orderId);

        kafka.send(TOPIC, orderId, message);

        await().atMost(Duration.ofSeconds(10))
                .until(() -> attempts.getOrDefault(orderId, List.of()).size() == 3);
        // Follow with a poison record: once it is dead-lettered, the first
        // record has long been committed, and it must not be there.
        String poison = "not json " + orderId;
        kafka.send(TOPIC, poison);
        awaitDeadLetter(poison);
        assertThat(deadLetterValues()).doesNotContain(message);
        assertThat(attempts.get(orderId)).hasSize(3);
    }

    @Test
    void invalidJsonIsDeadLetteredWithoutRetryAndConsumerCarriesOn() {
        String next = newOrderId();
        List<String> invalid = List.of(
                "not json at all",
                "{\"orderId\": \"1\", \"amount\": \"lots\"}",
                "null");
        invalid.forEach(message -> kafka.send(TOPIC, message));
        kafka.send(TOPIC, next, payment(next));

        invalid.forEach(this::awaitDeadLetter);
        await().atMost(Duration.ofSeconds(10))
                .until(() -> attempts.containsKey(next));
        assertThat(attempts.get(next)).hasSize(1);
    }

    @Test
    void missingOrderIsDeadLetteredWithoutRetryAndConsumerCarriesOn() {
        String missing = newOrderId();
        String next = newOrderId();
        failures.put(missing, attempt -> new OrderNotFoundException(missing));
        String message = payment(missing);

        kafka.send(TOPIC, missing, message);
        kafka.send(TOPIC, next, payment(next));

        awaitDeadLetter(message);
        await().atMost(Duration.ofSeconds(10))
                .until(() -> attempts.containsKey(next));
        assertThat(attempts.get(missing)).hasSize(1);
        assertThat(attempts.get(next)).hasSize(1);
    }

    @Test
    void successfulRecordIsProcessedOnce() {
        String orderId = newOrderId();

        kafka.send(TOPIC, orderId, payment(orderId));

        await().atMost(Duration.ofSeconds(10))
                .until(() -> attempts.containsKey(orderId));
        assertThat(attempts.get(orderId)).hasSize(1);
    }

    private final List<ConsumerRecord<String, String>> deadLetters =
            new CopyOnWriteArrayList<>();

    private ConsumerRecord<String, String> awaitDeadLetter(String value) {
        await().atMost(Duration.ofSeconds(15)).until(() -> {
            dlt.poll(Duration.ofMillis(200)).forEach(deadLetters::add);
            return deadLetterValues().contains(value);
        });
        return deadLetters.stream()
                .filter(record -> value.equals(record.value()))
                .findFirst().orElseThrow();
    }

    private List<String> deadLetterValues() {
        return deadLetters.stream().map(ConsumerRecord::value).toList();
    }

    private static String newOrderId() {
        return String.valueOf(Math.abs(UUID.randomUUID().getMostSignificantBits()));
    }

    private static String payment(String orderId) {
        return "{\"orderId\":\"" + orderId + "\",\"paymentId\":\"p-" + orderId
                + "\",\"amount\":1000}";
    }
}
