package dev.example.orders;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.converter.ConversionException;
import org.springframework.stereotype.Component;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.json.JsonMapper;

// Failures are handled by the error handler in KafkaErrorHandling.
@Component
public class PaymentSettledListener {

    private static final Logger log =
            LoggerFactory.getLogger(PaymentSettledListener.class);

    private final OrderService orders;
    private final JsonMapper json;

    public PaymentSettledListener(OrderService orders, JsonMapper json) {
        this.orders = orders;
        this.json = json;
    }

    @KafkaListener(topics = "payment-settled", groupId = "orders")
    public void on(String message) {
        PaymentSettled event = parse(message);
        log.info("payment-settled attempt for order {}", event.orderId());
        orders.markPaid(event);
    }

    // A message that does not parse never will, so it is not retried.
    private PaymentSettled parse(String message) {
        PaymentSettled event;
        try {
            event = json.readValue(message, PaymentSettled.class);
        } catch (JacksonException e) {
            throw new ConversionException("Not a PaymentSettled: " + message, e);
        }
        if (event == null) {
            throw new ConversionException("Not a PaymentSettled: " + message, null);
        }
        return event;
    }
}
